import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import {
  PAIRING_ALPHABET, PAIRING_ENCODED_LENGTH, PAIRING_SALT, PAIRING_SEED_BYTES,
  PAIRING_CONFLICT_ATTEMPTS,
  decodePairingSeed, derivePairing, encodePairingSeed, openPairingWindow,
} from "../src/pairing-seed";

// The v3 one-time pairing derivation (spec §9.1), against vectors a THIRD implementation produced.
//
// `protocol/fixtures/pairing-v3.json` was generated by stdlib Python, so this suite and
// `PairingSeedTests.swift` each agree with something neither side wrote. Two implementations that
// agree only with each other can be wrong together.
interface Case { name: string; seed: string; encoded: string; code: string; token: string; psk: string }
const fx = JSON.parse(readFileSync(
  fileURLToPath(new URL("../fixtures/pairing-v3.json", import.meta.url)), "utf8")) as
  { salt: string; alphabet: string; cases: Case[] };

const hex = (s: string) => new Uint8Array((s.match(/../g) ?? []).map((b) => parseInt(b, 16)));
const toHex = (b: Uint8Array) => [...b].map((x) => x.toString(16).padStart(2, "0")).join("");

test("the fixture and the implementation agree about the derivation's inputs", () => {
  expect(fx.salt).toBe(PAIRING_SALT);
  expect(fx.alphabet).toBe(PAIRING_ALPHABET);
  expect(fx.cases.length, "an empty fixture would pass every assertion below").toBeGreaterThan(0);
});

describe("cross-implementation vectors", () => {
  for (const c of fx.cases) {
    test(c.name, async () => {
      const seed = hex(c.seed);
      const m = await derivePairing(seed);
      expect(m).not.toBeNull();
      expect(m!.code).toBe(c.code);
      expect(m!.token).toBe(c.token);
      expect(toHex(m!.psk)).toBe(c.psk);
      expect(encodePairingSeed(seed)).toBe(c.encoded);
      expect(decodePairingSeed(c.encoded)).toEqual(seed);
    });
  }
});

// THE THREE OUTPUTS MUST BE INDEPENDENT KEY STREAMS. If `info` were ever dropped or shared, two of
// them would collide and the psk would be derivable from a value handed to the Control Plane. A
// length check alone would not notice.
// COMPARED AFTER THE SAME ENCODING, which is the only way this can discriminate. An earlier version
// compared the code STRING against the psk's HEX — representations that can never be equal whatever
// the bytes underneath — and it passed against a mutant that gave `psk` the `code` label.
test("the three outputs are distinct key streams", async () => {
  const m = (await derivePairing(new Uint8Array(PAIRING_SEED_BYTES).fill(7)))!;
  const pskAsCode = [...m.psk.slice(0, 8)].map((b) => PAIRING_ALPHABET[b % PAIRING_ALPHABET.length]).join("");
  expect(pskAsCode, "psk and code must not share an HKDF label").not.toBe(m.code);
  const t = new Uint8Array(m.psk.slice(0, 16));
  t[6] = (t[6]! & 0x0f) | 0x40; t[8] = (t[8]! & 0x3f) | 0x80;
  const pskAsToken = [...t].map((x) => x.toString(16).padStart(2, "0")).join("");
  expect(pskAsToken, "psk and token must not share an HKDF label").not.toBe(m.token.replace(/-/g, ""));
});

// Guards against a derivation that ignores its input — which a single-case fixture would not catch.
test("one bit of seed difference moves every output", async () => {
  const a = new Uint8Array(PAIRING_SEED_BYTES);
  const b = new Uint8Array(PAIRING_SEED_BYTES); b[PAIRING_SEED_BYTES - 1] = 1;
  const [ma, mb] = [(await derivePairing(a))!, (await derivePairing(b))!];
  expect(ma.code).not.toBe(mb.code);
  expect(ma.token).not.toBe(mb.token);
  expect(toHex(ma.psk)).not.toBe(toHex(mb.psk));
});

test("shapes the rest of the protocol depends on", async () => {
  const m = (await derivePairing(new Uint8Array(PAIRING_SEED_BYTES).fill(0xab)))!;
  expect(m.code).toHaveLength(8);
  expect(m.psk).toHaveLength(32);                       // Noise XXpsk3 takes exactly 32 bytes
  expect(m.token).toHaveLength(36);
  expect(m.token).toBe(m.token.toLowerCase());          // the session DO compares it as an exact string
  expect(m.token[14]).toBe("4");                        // version nibble
  expect("89ab").toContain(m.token[19]!);               // RFC 4122 variant
  expect([...m.code].every((ch) => PAIRING_ALPHABET.includes(ch))).toBe(true);
});

// A SEED OF THE WRONG LENGTH IS REFUSED, never padded or truncated: deriving from a short seed yields
// a well-formed pairing window with less entropy than any reader would assume.
test("a seed of the wrong length is refused", async () => {
  // 16 is the legal length now, so the wrong ones moved with it.
  for (const n of [0, 8, 15, 17, 32, 64]) {
    expect(await derivePairing(new Uint8Array(n).fill(1)), `${n} bytes`).toBeNull();
    expect(encodePairingSeed(new Uint8Array(n).fill(1)), `${n} bytes`).toBeNull();
  }
});

/**
 * The carrier is strict, and the negative controls are the point.
 *
 * **LENGTH IS THE DISCRIMINATOR NOW.** The `ss3.` prefix is gone, so nothing but the exact shape
 * separates a carrier from any other base64url text — which is why the wrong-length cases below are
 * load-bearing rather than tidy. A 30-character v2 room-token code still cannot be read as a secret,
 * for the same reason it could not before: it is the wrong length.
 */
test("the carrier refuses everything else", () => {
  const seed = new Uint8Array(PAIRING_SEED_BYTES).fill(3);
  const good = encodePairingSeed(seed)!;
  expect(good).toHaveLength(PAIRING_ENCODED_LENGTH);
  expect(good).toHaveLength(22);
  expect(decodePairingSeed(good)).toEqual(seed);
  expect(decodePairingSeed(`  ${good}\n`)).toEqual(seed);          // a pasted code may carry whitespace

  expect(decodePairingSeed(`${good}A`)).toBeNull();                 // one character too long
  expect(decodePairingSeed(good.slice(0, -1))).toBeNull();          // one too short
  expect(decodePairingSeed("1alQfiLoSeeKnQRcgpYMI65ubJGlGQ")).toBeNull(); // a retired v2 code
  expect(decodePairingSeed("")).toBeNull();
  expect(decodePairingSeed("!".repeat(22))).toBeNull();             // right length, not base64url
  expect(decodePairingSeed(`ss3.${good}`)).toBeNull();              // the old prefix is not accepted
  expect(PAIRING_SEED_BYTES).toBe(16);
});

// ------------------------------------------------------------------ opening a pairing window

describe("openPairingWindow", () => {
  const seedOf = (fill: number) => new Uint8Array(PAIRING_SEED_BYTES).fill(fill);

  test("registers only the two PUBLIC values", async () => {
    const sent: string[] = [];
    const res = await openPairingWindow("https://cp.test", {
      random: () => seedOf(7),
      post: async (_url, body) => { sent.push(body); return { status: 200, text: "{}" }; },
    });
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    const body = JSON.parse(sent[0]!) as Record<string, unknown>;
    expect(Object.keys(body).sort()).toEqual(["code", "token"]);
    expect(body.code).toBe(res.value.material.code);
    expect(body.token).toBe(res.value.material.token);
    // **THE SEED AND THE PSK NEVER LEAVE.** Asserted on the bytes actually sent, not on intent: a
    // Control Plane holding the seed can derive `psk` and complete the handshake itself.
    const wire = sent.join("");
    expect(wire).not.toContain(res.value.carrier);
    expect(wire).not.toContain(res.value.carrier.slice(4));
    for (const b of res.value.material.psk) expect(wire).not.toContain(String(b).repeat(8));
  });

  test("the carrier is the seed, and it derives the same material back", async () => {
    const res = await openPairingWindow("https://cp.test", {
      random: () => seedOf(3), post: async () => ({ status: 200, text: "{}" }),
    });
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    const decoded = decodePairingSeed(res.value.carrier)!;
    expect([...decoded]).toEqual([...seedOf(3)]);
    const again = await derivePairing(decoded);
    expect(again!.code).toBe(res.value.material.code);
    expect(again!.token).toBe(res.value.material.token);
    expect([...again!.psk]).toEqual([...res.value.material.psk]);
  });

  // §9.2: "A temporary pairing-route conflict can be retried with fresh material, at most four
  // times." FRESH material — retrying the same seed would ask for the same seized code forever.
  test("a conflict is retried with a NEW seed, four times at most", async () => {
    const seeds: string[] = [];
    let n = 0;
    const res = await openPairingWindow("https://cp.test", {
      random: () => seedOf(++n),
      post: async (_u, body) => { seeds.push(body); return { status: 409, text: "{}" }; },
    });
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.failure).toBe("conflict");
    expect(seeds).toHaveLength(PAIRING_CONFLICT_ATTEMPTS);
    expect(new Set(seeds).size).toBe(PAIRING_CONFLICT_ATTEMPTS);
  });

  test("a conflict that clears succeeds on a later attempt", async () => {
    let n = 0;
    const res = await openPairingWindow("https://cp.test", {
      random: () => seedOf(++n),
      post: async () => (n < 3 ? { status: 409, text: "{}" } : { status: 200, text: "{}" }),
    });
    expect(res.ok).toBe(true);
  });

  // A refusal is not a conflict: retrying fresh material against a Worker that says 400 would burn
  // the budget on an answer that will not change.
  test("a refusal stops immediately", async () => {
    let calls = 0;
    const res = await openPairingWindow("https://cp.test", {
      random: () => seedOf(1),
      post: async () => { calls++; return { status: 400, text: "{}" }; },
    });
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.failure).toBe("refused");
    expect(calls).toBe(1);
  });

  test("an unreachable control plane is its own answer", async () => {
    const res = await openPairingWindow("https://cp.test", {
      random: () => seedOf(1),
      post: async () => { throw new Error("network"); },
    });
    expect(res.ok).toBe(false);
    if (!res.ok) expect(res.failure).toBe("unreachable");
  });
});
